// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Give the contract 5 ether via fallback
        vm.deal(address(this), 5 ether);
        (bool sent, ) = address(c).call{value: 5 ether}("");
        require(sent, "send failed");

        // Owner (this contract) calls withdrawAll to recipient (also this contract)
        vm.prank(address(this));
        c.withdrawAll(address(this));

        // The reference sends the whole balance, so c balance becomes 0.
        // The bug sends 0, so c balance remains 5 ether.
        assertEq(address(c).balance, 0);
    }
}

