pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract with 1 ether via fallback
        vm.deal(address(this), 1 ether);
        address(c).call{value: 1 ether}("");

        // Prepare recipient
        address recipient = address(0x123);
        uint256 initialBalance = address(recipient).balance;

        // Owner (this) calls withdrawAll
        vm.prank(address(this));
        c.withdrawAll(recipient);

        // Assert: reference transfers full balance, buggy transfers zero
        assertEq(address(recipient).balance - initialBalance, 1 ether);
    }
}

