pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Send some ether to the contract so that withdrawAll can transfer
        vm.deal(address(this), 1 ether);
        payable(address(c)).transfer(1 ether);
        // Owner (this contract) calls withdrawAll
        c.withdrawAll(address(0x1234));
        // Assert that the contract still has code (i.e., not selfdestructed)
        assertTrue(address(c).code.length > 0);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract via fallback
        vm.deal(address(this), 1 ether);
        (bool success, ) = address(c).call{value: 1 ether}("");
        require(success);

        // withdrawAll to a different recipient
        address recipient = address(0x123);
        c.withdrawAll(recipient);

        // The reference contract still exists (balance 0), selfdestruct destroys it (balance 0 too)
        // But we can check the contract still has code in reference, no code in buggy version
        // Simpler: after withdrawAll, reference allows another call, buggy version reverts because contract is destroyed
        (bool ok, ) = address(c).call("");
        assertTrue(ok);
    }
}

