pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        // Fund the contract so selfdestruct is payable
        vm.deal(address(c), 1 ether);
        // Owner (this) calls withdrawAll with a recipient
        c.withdrawAll(address(0x1234));
        // After the call, the reference keeps the contract alive; buggy selfdestructs it
        uint256 codeSize;
        assembly {
            codeSize := extcodesize(c)
        }
        assertTrue(codeSize > 0);
    }
}
